export const SORT_FIELDS = [
  "title",
  "price",
  "stock",
] as const;

export type Review = {
  rating: number;
  comment: string;
  reviewerName: string;
};

export type Product = {
  id: string;
  name: string;
  title: string;
  price: number;
  stock: number;
  category: string;
  thumbnail: string;
  description: string;
  reviews: Review[];
};

export type ProductDraft = {
  title: string;
  price: number;
  stock: number;
  category: string;
  thumbnail: string;
  description: string;
};

export type ProductList = {
  products: Product[];
  total: number;
};

export type SearchQuery = {
  q: string;
  limit: number;
  sortBy: (typeof SORT_FIELDS)[number];
};

export const ProductDraftSchema = z.object({
  title: z.string().min(1, "กรุณากรอกชื่อสินค้า"),
  price: z.number().min(0, "ราคาต้องไม่ติดลบ"),
  stock: z.number().min(0, "จำนวนสินค้าต้องไม่ติดลบ"),
  category: z.string().min(1, "กรุณาเลือกหมวดหมู่"),
  thumbnail: z
    .string()
    .url("กรุณากรอก URL รูปภาพที่ถูกต้อง"),
  description: z
    .string()
    .min(1, "กรุณากรอกรายละเอียด"),
});

export const SearchQuerySchema = z.object({
  q: z.string(),
  limit: z.number().min(1).max(100),
  sortBy: z.enum(SORT_FIELDS),
});

export const defaultQuery: SearchQuery = {
  q: "",
  limit: 10,
  sortBy: "title",
};

/* =========================
   Local products
   ใช้เก็บสินค้าที่เพิ่มจากฟอร์ม
========================= */

declare global {
  var demoProducts: Product[] | undefined;
}

const products =
  globalThis.demoProducts ?? [];

if (process.env.NODE_ENV !== "production") {
  globalThis.demoProducts = products;
}

/* =========================
   Get local products
========================= */

export function getProducts() {
  return products;
}

/* =========================
   Get product by ID
========================= */

export function getProduct(id: string) {
  return products.find(
    (product) => product.id === id,
  );
}

/* =========================
   Add product
========================= */

export function addProduct(
  product: ProductDraft,
) {
  const newProduct: Product = {
    ...product,
    id: `p${Date.now()}`,
    name: product.title,
    reviews: [],
  };

  products.push(newProduct);

  return newProduct;
}

/* =========================
   Update product
========================= */

export function updateProduct(
  id: string,
  values: Pick<
    Product,
    "name" | "price" | "description"
  >,
) {
  const product = getProduct(id);

  if (!product) {
    throw new Error("Product not found");
  }

  product.name = values.name;
  product.title = values.name;
  product.price = values.price;
  product.description = values.description;
}

/* =========================
   Delete product
========================= */

export function deleteProduct(id: string) {
  const index = products.findIndex(
    (product) => product.id === id,
  );

  if (index === -1) {
    throw new Error("Product not found");
  }

  products.splice(index, 1);
}

/* =========================
   DummyJSON API
========================= */

type DummyJsonProduct = {
  id: number;
  title: string;
  price: number;
  stock: number;
  category: string;
  thumbnail: string;
  description: string;
  reviews?: {
    rating: number;
    comment: string;
    reviewerName: string;
  }[];
};

type DummyJsonResponse = {
  products: DummyJsonProduct[];
  total: number;
  skip: number;
  limit: number;
};

/* =========================
   Fetch products
========================= */

export async function fetchProducts(
  query: SearchQuery,
): Promise<ProductList> {
  const params = new URLSearchParams();

  params.set("limit", String(query.limit));
  params.set("sortBy", query.sortBy);
  params.set("sortOrder", "asc");

  let url =
    "https://dummyjson.com/products";

  const keyword = query.q.trim();

  if (keyword) {
    params.set("q", keyword);

    url =
      "https://dummyjson.com/products/search";
  }

  const response = await fetch(
    `${url}?${params.toString()}`,
    {
      cache: "no-store",
    },
  );

  if (!response.ok) {
    throw new Error(
      "เรียกข้อมูลสินค้าไม่สำเร็จ",
    );
  }

  const data =
    (await response.json()) as DummyJsonResponse;

  const apiProducts: Product[] =
    data.products.map((product) => ({
      id: String(product.id),
      name: product.title,
      title: product.title,
      price: product.price,
      stock: product.stock,
      category: product.category,
      thumbnail: product.thumbnail,
      description: product.description,
      reviews:
        product.reviews ?? [],
    }));

  return {
    products: apiProducts,
    total: data.total,
  };
}